lab.solution:
class FakeNotifier:
    def __init__(self):
        self.sent = []

    def send(self, learner_id, lesson_id):
        self.sent.append((learner_id, lesson_id))

def mark_done(notifier, learner_id, lesson_id):
    if not learner_id or not lesson_id:
        raise ValueError('IDs are required')
    notifier.send(learner_id, lesson_id)
    return {'ok': True}

fake = FakeNotifier()
assert mark_done(fake, 'ana', 'loops') == {'ok': True}
assert fake.sent == [('ana', 'loops')]
rejected = FakeNotifier()
try:
    mark_done(rejected, 'ana', '')
except ValueError:
    pass
else:
    raise AssertionError('missing ID should fail')
assert rejected.sent == []
print('success and rejection boundaries checked')

